	t.Run("SetRef", func(t *testing.T) {
		obj := &FormFieldUnknown{}
		var fernTestValueRef *FormFieldRef
		obj.SetRef(fernTestValueRef)
		assert.Equal(t, fernTestValueRef, obj.Ref)
		assert.NotNil(t, obj.explicitFields)
	})

